set -euo pipefail
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gunzipSync} from 'node:zlib';import {createRequire} from 'node:module';import {DatabaseSync} from 'node:sqlite';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),report=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-remaining29-20261122/vn-variant.json')),p=report.fresh.find(p=>p.url.includes('/user/'));if(p?.file){const $=ch.load(gunzipSync(fs.readFileSync(p.file)).toString());console.log(JSON.stringify({url:p.url,title:$('title').text(),h1:$('h1').text(),canonical:$('link[rel=canonical]').attr('href'),schemas:$('script[type="application/ld+json"]').map((i,e)=>$(e).text().slice(0,1800)).get(),profile:$('body').text().replace(/\s+/g,' ').slice(0,1300)}));}const db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true});console.log(JSON.stringify({counts:db.prepare("SELECT parse_status,count(*) n FROM article_links WHERE site='vntravel.org.vn' AND url LIKE 'https://vntravel.org.vn/user/%' GROUP BY parse_status").all(),examples:db.prepare("SELECT url,parse_status,error FROM article_links WHERE site='vntravel.org.vn' AND url LIKE 'https://vntravel.org.vn/user/%' LIMIT 6").all()}));db.close();
